string to_lower_copy(string const& s)
{
    string cpy(s);
    for (auto& c: cpy) {
        c = tolower(c);
    }
    return cpy;
}

string normalize(string const& text)
{
    string result;
    copy_if(text.begin(), text.end(), back_inserter(result),
        [](const char c) { return !isspace(c) && !ispunct(c); });
    return to_lower_copy(result);
}

